types.definition:
export type ChartLabelFormatter = (
  value: string | number,
  datum: ChartDatum
) => React.ReactNode

export interface ChartSeries {
  /** 数据字段名。 */
  key: string
  /** 图例和提示框中显示的名称。 */
  label?: string
  /** 覆盖当前序列的颜色。 */
  color?: string
  /** 折线序列的 SVG 虚线模式。 */
  strokeDasharray?: string
}

export type ChartValueFormatter = (
  value: number,
  series: ChartSeries,
  datum: ChartDatum
) => React.ReactNode
